// Packages:
// - ModelContextProtocol --version 1.*
// - Microsoft.Extensions.DependencyInjection
// - Microsoft.Extensions.Logging

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Logging.AddConsole();

builder.Services.AddMcpServer(options =>
{
    options.ServerName = "support-server";
    options.ServerVersion = "1.0.0";
})
.WithTools<SupportTools>()
.WithPrompts<SupportPrompts>()
.WithStdioTransport();

var host = builder.Build();

// Expected: server initializes, negotiates capabilities, and waits for requests
await host.RunAsync();

// Sample output on startup:
// [INFO] MCP server 'support-server' v1.0.0 started on stdio
// [INFO] Capabilities: tools, prompts
